import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Agent Systems Group Guide","description":"From single actions to autonomous loops: mental model, patterns, state and recovery, control plane, and scale — a ten-page navigation.","frontmatter":{"title":"Agent Systems Group Guide","description":"From single actions to autonomous loops: mental model, patterns, state and recovery, control plane, and scale — a ten-page navigation.","domain":"tech","tags":["tech","agent-systems","navigation"],"navOrder":59,"topicId":"agent-systems-guide","layer":"6","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[],"prerequisites":["tool-execution"],"next":["agent-runtime","workflow","recovery-hitl"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/06-agent-systems/index.md","filePath":"tech/06-agent-systems/index.md","lastUpdated":1791115887000}'),n={name:"tech/06-agent-systems/index.md"};function s(i,e,d,l,u,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="agent-systems-group-guide" tabindex="-1">Agent Systems Group Guide <a class="header-anchor" href="#agent-systems-group-guide" aria-label="Permalink to &quot;Agent Systems Group Guide&quot;">​</a></h1><blockquote><p><strong>Group</strong>: Agent Systems | <strong>Previous group exit</strong>: define and safely execute one controlled action | <strong>This group exit</strong>: build a stateful, recoverable, permission-bounded autonomous loop</p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>BLUF</strong>: this group upgrades a <em>single action</em> into a <em>sustained loop</em>: the model observes, decides, and acts until a stop condition fires. Autonomy brings new failure modes — state bloat, runaway loops, error propagation, unsupervised side effects. Ten pages run from mental model, through patterns, to control plane and scale.</p><table tabindex="0"><thead><tr><th>Order</th><th>Page</th><th>Question it answers</th></tr></thead><tbody><tr><td>Front door</td><td><a href="./agent-runtime.html">Mental model &amp; runtime</a></td><td>What composes the loop? When is an agent worth it?</td></tr><tr><td>Patterns</td><td><a href="./design-patterns.html">Design patterns</a></td><td>ReAct, routing, planner-executor, reflection — which and when?</td></tr><tr><td>State</td><td><a href="./state-memory.html">State &amp; memory</a></td><td>Where do cross-step / cross-turn data live, and how to recover?</td></tr><tr><td>Control plane</td><td><a href="./hooks.html">Hooks</a></td><td>Lifecycle interception and automated policy gates</td></tr><tr><td>Control plane</td><td><a href="./recovery-hitl.html">Recovery &amp; HITL</a></td><td>Which state do you return to? When must a human decide?</td></tr><tr><td>Environment fit</td><td><a href="./computer-use.html">Computer use</a></td><td>observe→act→verify when only a visual UI exists</td></tr><tr><td>Deterministic alternative</td><td><a href="./workflow.html">Workflow patterns</a></td><td>When <strong>not</strong> to use an agent</td></tr><tr><td>Capability packaging</td><td><a href="./skills.html">Skills</a> · <a href="./plugins.html">Plugins</a></td><td>Distributing procedural knowledge and capability packages</td></tr><tr><td>Scale</td><td><a href="./multi-agent.html">Subagent / multi-agent</a></td><td>Delegation and orchestration within one trust domain</td></tr></tbody></table><p><strong>Boundary</strong>: delegation across processes, organizations, or trust domains is not here — go through <a href="./../07-interoperability/">Interoperability</a> (A2A et al.) first.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><ul><li>First contact with agents: read top-down starting from <a href="./agent-runtime.html">Mental model &amp; runtime</a>.</li><li>Already running agents in production: jump to <a href="./recovery-hitl.html">Recovery &amp; HITL</a> and <a href="./hooks.html">Hooks</a>.</li><li>Unsure an agent is warranted: read the reverse decision in <a href="./workflow.html">Workflow patterns</a> first.</li></ul><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>Three loop invariants: <strong>stop conditions must be explicit</strong> (steps / tokens / wall-clock budget), <strong>state must be checkpointable</strong>, <strong>side effects must pass Action-group execution discipline</strong>. Missing any one, autonomy only amplifies failure.</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>Pages share one debugging grammar: symptom → evidence (trace / checkpoint) → fix → done criteria. The multi-agent debug unit is the delegation; the single-agent unit is the loop step.</p><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Each topic page carries its own four-tier route; group-level entries are Anthropic&#39;s <em>Building Effective Agents</em> and the OpenAI Agents guide (see agent-runtime resource tables).</p>',14)])])}const y=t(n,[["render",s]]);export{f as __pageData,y as default};
